<script setup>import DonorBadge from '../components/DonorBadge.vue';import {ref} from 'vue';import {readStore,writeStore} from '../data/storage.js';import {BookOpen,CheckCircle2,Megaphone} from 'lucide-vue-next';const completed=ref(readStore('achievements',[]));const goals=['Прочитав матеріал про донорство','Пройшов навчальний тест','Допоміг в інформаційній кампанії'];function toggle(goal){completed.value=completed.value.includes(goal)?completed.value.filter(x=>x!==goal):[...completed.value,goal];writeStore('achievements',completed.value)}</script><template><div class="page-intro"><h1>Мій шлях допомоги</h1><p>Рівні та значки відображають участь, волонтерство та навчання.</p></div><section class="profile-hero surface"><div class="profile-avatar">♡</div><h2>Рівень: Помічник</h2></section><section class="section"><h2>Етапи залученості</h2><div class="badge-set"><DonorBadge title="Новачок"/><DonorBadge title="Помічник" tone="pink"/><DonorBadge title="Досвідчений" tone="lavender"/><DonorBadge title="Освітній волонтер"/></div></section><section class="section surface checklist-panel"><h2>Навчальні досягнення</h2><label v-for="goal in goals" :key="goal" class="goal-line"><input type="checkbox" :checked="completed.includes(goal)" @change="toggle(goal)"/>{{goal}}</label></section><section class="section"><h2>Моя активність</h2><div class="stats-grid"><div class="surface stat-card"><BookOpen/><div><strong>Прочитані матеріали</strong><b>6</b></div></div><div class="surface stat-card"><CheckCircle2/><div><strong>Запити підтримано</strong><b>3</b></div></div><div class="surface stat-card"><Megaphone/><div><strong>Участь у кампаніях</strong><b>2</b></div></div></div></section></template>